TITLE_ONLY = {"fig-dm-skip": ("Loss when one layer is deleted, 48 layers", "删掉一层后的损失，48 层")}

# body text outside figures
SUBS = [
 ("from 130m to 1.2B.", "from 130m to 1.2b."), ("规模从 130m 到 1.2B", "规模从 130m 到 1.2b"),
 ('<p class="hyp-answer" lang="en">In the features. Retraining', '<p class="hyp-answer" lang="en">The gap is in the features. Retraining'),
]

def esc(t):
    return html.escape(t, quote=True)

def main(path):
    s = open(path).read()
    for fid, (ten, tzh, cen, czh) in NEW.items():
        m = re.search(r'<figure class="viz" id="%s"[^>]*></figure>\n' % re.escape(fid), s, flags=re.S)
        assert m, fid
        blk = m.group(0)
        new = blk
        for attr, val in (("data-title-en", ten), ("data-title-zh", tzh), ("data-cap-en", cen), ("data-cap-zh", czh)):
            if val is None:
                continue
            assert ", so " not in val or fid in ("fig-dm-write",), (fid, "so")
            new, n = re.subn(r'%s="[^"]*"' % attr, '%s="%s"' % (attr, esc(val)), new)
            assert n == 1, (fid, attr)
        add = "".join('  <p lang="en">%s</p>\n  <p lang="zh">%s</p>\n' % (esc(e), esc(z)) for e, z in BODY.get(fid, []))
        s = s.replace(blk, new + add)
        print("rewrote", fid, "+%d body paragraphs" % len(BODY.get(fid, [])))
    for fid, (ten, tzh) in TITLE_ONLY.items():
        pass
    for a, b in SUBS:
        assert s.count(a) == 1, a
        s = s.replace(a, b)
    open(path, "w").write(s)

if __name__ == "__main__":
    main(sys.argv[1])
